func meal(id, title, slot, diet string, minutes int, ingredients []Ingredient, steps []string, allergens ...string) Recipe {
	diets := []string{"balanced"}
	if diet == "vegetarian" || diet == "vegan" {
		diets = append(diets, "vegetarian")
	}
	if diet == "vegan" {
		diets = append(diets, "vegan")
	}
	return Recipe{
		ID: id, Title: title, Meals: []string{slot}, Diets: diets, PrepMinutes: minutes,
		Servings: 1, Ingredients: ingredients, Steps: steps, Allergens: append([]string{}, allergens...),
		Components: []string{"vegetables", "wholegrain", "protein"},
	}
}
